int anzahl = 0;
Parallel.For(0, 5_000_000, i =>
{
    if (IstPrim(i))
        Interlocked.Increment(
            ref anzahl);
});
Console.WriteLine(anzahl); // 348513

async Task<int> Lade(string n)
{
    await Task.Delay(300);
    return n.Length;
}
int[] r = await Task.WhenAll(
    Lade("Mathe"), Lade("POS"),
    Lade("NVS"));
Console.WriteLine(r.Sum()); // 11
// Dauer ≈ 300 ms, nicht 900 ms
